import {actionLabels,variableLabel} from './control-labels.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function validateUI(ui){return ui===undefined||Array.isArray(ui)&&ui.length<=100&&ui.every(e=>e&&typeof e.id==='string'&&['label','counter','bar','button'].includes(e.type)&&typeof e.text==='string'&&e.text.length<=120&&['x','y','w','h','fontSize','value'].every(k=>Number.isFinite(e[k]))&&e.x>=0&&e.y>=0&&e.w>0&&e.h>0&&e.x+e.w<=100.01&&e.y+e.h<=100.01&&Math.abs(e.value)<=1e6&&(e.max===undefined||Number.isFinite(e.max)&&e.max>0&&e.max<=1e9)&&e.fontSize>=8&&e.fontSize<=72&&/^#[\da-f]{6}$/i.test(e.color)&&/^#[\da-f]{6}$/i.test(e.textColor)&&['none','jump','slide','left','right','addvariable','setvariable','restart'].includes(e.action)&&(!e.variable||typeof e.variable==='string'&&e.variable.length<=40))}
export function createUIElement(type='counter',variable='Score'){return{id:crypto.randomUUID(),type,text:type==='button'?'Jump':type==='bar'?'Health':type==='label'?'Your text':'Coins',variable:type==='label'?'':variable,x:4,y:5,w:25,h:10,fontSize:20,color:'#56368c',textColor:'#ffffff',action:type==='button'?'jump':'none',value:1,max:3}}
export function mountGameUI(host,project,getState,onAction){const layer=document.createElement('div');layer.className='game-ui-layer';layer.style.cssText='position:absolute;inset:0;pointer-events:none;z-index:5;container-type:inline-size';host.append(layer);let previous='';function update(){const state=getState();layer.hidden=!state;if(!state)return;const markup=(project.ui||[]).map(e=>{const v=e.variable==='Score'?state.score:e.variable==='Health'?state.health:Number(state.variables?.[e.variable])||0,content=e.type==='counter'?`${escape(e.text)} ${v.toFixed(v%1?1:0)}`:e.type==='bar'?`${escape(e.text)} <meter min="0" max="${Math.max(1,e.max||3)}" value="${v}"></meter> ${v}`:escape(e.text),tag=e.type==='button'?'button':'div';return`<${tag} data-ui-id="${escape(e.id)}" style="position:absolute;box-sizing:border-box;left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;display:flex;align-items:center;justify-content:center;gap:5px;border:0;border-radius:5px;background:${e.color};color:${e.textColor};font:600 clamp(10px,${e.fontSize/9.6}cqw,${e.fontSize}px) Montserrat;overflow:hidden;${tag==='button'?'pointer-events:auto;touch-action:manipulation;cursor:pointer':''}">${content}</${tag}>`}).join('');if(markup!==previous){layer.innerHTML=markup;previous=markup}}layer.addEventListener('pointerdown',e=>e.stopPropagation());layer.addEventListener('click',e=>{const entry=project.ui?.find(item=>item.id===e.target.closest('[data-ui-id]')?.dataset.uiId);if(entry?.type==='button'){e.preventDefault();onAction(entry)}});const timer=setInterval(update,80);update();return()=>{clearInterval(timer);layer.remove()}}
export function openUIBuilder(project,onSave,notify=()=>{}){const draft=structuredClone(project.ui||[]);let selected=draft[0]?.id;const d=document.createElement('dialog');d.className='editor-dialog ui-builder';d.style.cssText='width:min(960px,96vw);max-width:96vw';d.innerHTML=`<h2>Game UI</h2><div style="display:flex;flex-wrap:wrap;gap:8px">${['label','counter','bar','button'].map(t=>`<button data-add="${t}">+ ${{label:'Text',counter:'Counter',bar:'Progress bar',button:'Button'}[t]}</button>`).join('')}<button id="ui-coins">Coins counter</button><button id="ui-health">Health bar</button><button id="ui-jump">Jump button</button></div><div id="ui-preview" style="position:relative;aspect-ratio:16/9;background:#141923;border:1px solid #555;margin:12px 0;touch-action:none;overflow:hidden"></div><form id="ui-fields" style="display:flex;flex-wrap:wrap;gap:8px"></form><footer style="display:flex;gap:10px;margin-top:16px"><button id="ui-cancel">Cancel</button><button id="ui-save" class="primary">Save UI</button></footer>`;document.body.append(d);const preview=d.querySelector('#ui-preview'),fields=d.querySelector('#ui-fields');function add(type,variable){const e=createUIElement(type,variable);e.y=Math.min(85,5+draft.length*12);draft.push(e);selected=e.id;render()}const newVariables={};function render(){preview.innerHTML=draft.map(e=>`<button type="button" data-select="${escape(e.id)}" style="position:absolute;left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;background:${e.color};color:${e.textColor};border:2px solid ${e.id===selected?'#c599ff':'transparent'};font-size:${Math.min(e.fontSize,24)}px;overflow:hidden;touch-action:none">${escape(e.text)}${e.type==='counter'?' { '+escape(variableLabel(e.variable))+' }':e.type==='bar'?' ▰▰▰':''}</button>`).join('');const e=draft.find(e=>e.id===selected);fields.innerHTML=e?`<label>Text<input data-field="text" maxlength="120" value="${escape(e.text)}"></label>${e.type==='counter'||e.type==='bar'||e.type==='button'&&['addvariable','setvariable'].includes(e.action)?`<label>${e.type==='button'?'Which counter?':'Show counter'}<select data-field="variable"><option value="">Choose a counter</option>${Object.keys({...project.variables,...newVariables}).map(v=>`<option value="${escape(v)}" ${v===e.variable?'selected':''}>${escape(variableLabel(v))}</option>`).join('')}</select></label><button type="button" id="ui-create-variable">+ Create counter</button>`:''}${[['x','Left %'],['y','Top %'],['w','Width %'],['h','Height %'],['fontSize','Font size'],...(e.type==='bar'?[['max','Full bar value']]:[]),...(e.type==='button'&&['addvariable','setvariable'].includes(e.action)?[['value',e.action==='addvariable'?'Amount to add':'New counter value']]:[])].map(([k,l])=>`<label>${l}<input style="width:80px" type="number" step="1" data-field="${k}" value="${e[k]??3}"></label>`).join('')}<label>Background<input type="color" data-field="color" value="${e.color}"></label><label>Text color<input type="color" data-field="textColor" value="${e.textColor}"></label>${e.type==='button'?`<label>On click<select data-field="action">${(project.dimension==='3d'?['none','jump','slide','left','right','addvariable','setvariable','restart']:['none','jump','left','right','addvariable','setvariable','restart']).map(a=>`<option value="${a}" ${a===e.action?'selected':''}>${project.dimension==='3d'&&project.runner?.enabled&&['left','right'].includes(a)?'Switch lane '+a:actionLabels[a]}</option>`).join('')}</select></label>`:'<span>Display only · lets clicks through</span>'}<button type="button" id="ui-remove">Remove selected</button>`:'Add an element to get started.';fields.querySelectorAll('[data-field]').forEach(input=>input.onchange=()=>{e[input.dataset.field]=input.type==='number'?Number(input.value):input.value;e.w=Math.max(3,Math.min(100,e.w));e.h=Math.max(3,Math.min(100,e.h));e.x=Math.max(0,Math.min(100-e.w,e.x));e.y=Math.max(0,Math.min(100-e.h,e.y));e.fontSize=Math.max(8,Math.min(72,e.fontSize));render()});fields.querySelector('#ui-create-variable')?.addEventListener('click',()=>{const name=prompt('Name your counter, for example Coins collected');if(!name?.trim())return;const key=name.trim();if(key.length>40){notify('Keep counter names under 40 characters.');return}if(!Object.hasOwn(project.variables||{},key)&&!Object.hasOwn(newVariables,key))newVariables[key]=0;e.variable=key;render()});fields.querySelector('#ui-remove')?.addEventListener('click',()=>{draft.splice(draft.indexOf(e),1);selected=draft[0]?.id;render()});preview.querySelectorAll('[data-select]').forEach(b=>b.onpointerdown=event=>{const item=draft.find(e=>e.id===b.dataset.select);selected=item.id;const r=preview.getBoundingClientRect(),start={x:event.clientX,y:event.clientY,ox:item.x,oy:item.y};b.setPointerCapture(event.pointerId);b.onpointermove=move=>{item.x=Math.round(Math.max(0,Math.min(100-item.w,start.ox+(move.clientX-start.x)/r.width*100)));item.y=Math.round(Math.max(0,Math.min(100-item.h,start.oy+(move.clientY-start.y)/r.height*100)));b.style.left=item.x+'%';b.style.top=item.y+'%'};b.onpointerup=b.onpointercancel=()=>{b.onpointermove=null;render()}})}fields.onsubmit=e=>e.preventDefault();d.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>add(b.dataset.add,b.dataset.add==='bar'?'Health':b.dataset.add==='button'?'Jumps':'Score'));d.querySelector('#ui-coins').onclick=()=>add('counter','Score');d.querySelector('#ui-health').onclick=()=>add('bar','Health');d.querySelector('#ui-jump').onclick=()=>add('button','Jumps');d.querySelector('#ui-cancel').onclick=()=>d.close();d.querySelector('#ui-save').onclick=()=>{if(draft.some(e=>(e.type==='counter'||e.type==='bar'||e.type==='button'&&['addvariable','setvariable'].includes(e.action))&&!e.variable)){notify('Choose a counter for each counter, bar, or counter button.');return}if(!validateUI(draft)){notify('Check UI positions, sizes and values.');return}project.variables={...project.variables,...newVariables};project.ui=draft;onSave();d.close()};d.addEventListener('close',()=>d.remove());render();d.showModal()}
